const money=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2});
const pct=n=>`${(n*100).toFixed(1)}%`;
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let scan,group='shortlist',selected='RDDT';
const members=()=>scan.candidates.filter(r=>group==='shortlist'?scan.shortlist.includes(r.ticker):!scan.shortlist.includes(r.ticker));
function render(){
 document.querySelectorAll('[data-group]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.group===group)));
 document.getElementById('candidates-panel').setAttribute('aria-labelledby',group+'-tab');
 document.getElementById('group-note').textContent=group==='shortlist'?'Ranked by AI opportunity and earnings consistency. Option liquidity still needs checking.':'Research only: these names have consistency, earnings-quality or macro exceptions. They do not all meet the strict screen.';
 document.getElementById('rows').innerHTML=members().map(r=>`<tr class="${r.ticker===selected?'selected-row':''}"><td><button class="company-button" data-ticker="${safe(r.ticker)}" aria-label="View ${safe(r.company)}" aria-pressed="${r.ticker===selected}"><strong><i>${String(r.rank).padStart(2,'0')}</i>${safe(r.ticker)}</strong><small>${safe(r.company)}</small></button></td><td class="positive">+${pct(r.revenueGrowth)}</td><td class="drawdown">−${pct(1-r.price/r.high)}</td><td>${money.format(r.price)}</td></tr>`).join('');
 const r=scan.candidates.find(r=>r.ticker===selected),short=scan.shortlist.includes(selected);
 const ni=r.netIncome>=1000?`$${(r.netIncome/1000).toFixed(2)}B`:`$${r.netIncome.toFixed(0)}M`;
 const report=short?`<a class="card-link" href="cards/${safe(r.ticker)}-2026-10-07.png" download><svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4" stroke="currentColor" stroke-width="1.8"/></svg>Download ${safe(r.ticker)} research image</a><a class="card-link" href="cards/${safe(r.ticker)}-2026-10-07.png" target="_blank" rel="noopener">View image card</a>`:'';
 document.getElementById('detail').innerHTML=`<div class="detail-head"><div><h2>${safe(r.ticker)}</h2><p>${safe(r.company)}</p></div><span class="badge ${short?'':'exception'}">${short?'RESEARCH SHORTLIST':'EXCEPTION / WATCH'}</span></div><div class="metrics"><div><span>TTM revenue YoY</span><strong class="positive">+${pct(r.revenueGrowth)}</strong></div><div><span>TTM net income</span><strong>${ni}</strong></div><div><span>TTM profit YoY</span><strong class="positive">${r.netGrowth===null?'Turned positive':'+'+pct(r.netGrowth)}</strong></div></div><div class="detail-copy"><div class="quality">${safe(r.quality)}</div><h3>The catalyst</h3><p>${safe(r.catalyst)}</p><h3>What could break the thesis</h3><p>${safe(r.risk)}</p><h3>LEAPS availability</h3><p class="small">${safe(r.options)}</p><h3>Drawdown reference</h3><p class="small">${money.format(r.price)} vs. ${money.format(r.high)} ${safe(r.basis)} high · ${pct(1-r.price/r.high)} below. Prices as of Oct 6, 2026 close.</p>${report}<div class="sources"><a href="${safe(r.primary)}" target="_blank" rel="noopener">Company results</a><a href="${safe(r.overview)}" target="_blank" rel="noopener">Financial overview</a><a href="${safe(r.highSource)}" target="_blank" rel="noopener">High reference</a></div></div>`;
}
function choose(ticker){const r=scan?.candidates.find(r=>r.ticker===ticker);if(!r)throw new Error('Unknown candidate');selected=ticker;group=scan.shortlist.includes(ticker)?'shortlist':'broader';render();return {ticker,group,price:r.price,asOf:scan.asOf,drawdown:1-r.price/r.high,catalyst:r.catalyst};}
document.addEventListener('click',e=>{const button=e.target.closest('[data-ticker],[data-group]');if(!button||!scan)return;if(button.dataset.group){group=button.dataset.group;selected=members()[0].ticker;render();}else{choose(button.dataset.ticker);if(matchMedia('(max-width:760px)').matches)document.querySelector('.detail').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});}});
document.querySelector('.tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const target=e.key==='Home'?'shortlist':e.key==='End'?'broader':group==='shortlist'?'broader':'shortlist';document.getElementById(target+'-tab').click();document.getElementById(target+'-tab').focus();});
async function start(){try{const res=await fetch('data/scan-2026-10-07.json');if(!res.ok)throw new Error('Research file unavailable');scan=await res.json();render();const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{await context.registerTool({name:'view_leap_candidate',title:'View LEAPS candidate',description:'Select a researched ticker and display its dated metrics, catalyst and risks. Does not place trades or refresh quotes.',inputSchema:{type:'object',properties:{ticker:{type:'string'}},required:['ticker'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.ticker!=='string'||Object.keys(input).some(k=>k!=='ticker'))throw new Error('Supply one ticker string');return choose(input.ticker.toUpperCase());}},{signal:lifecycle.signal});}catch(e){console.info('Candidate tool unavailable',e.message);}}}catch(e){document.getElementById('rows').innerHTML='<tr><td colspan="4">Research could not load. Reload to try again.</td></tr>';document.getElementById('detail').innerHTML='<p class="error">Research is temporarily unavailable. The workbook and image downloads remain accessible.</p>';}}
start();
